import{_ as a,o,c as r,ag as t}from"./chunks/framework.WIXs2PCf.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"troubleshooting.md"};function i(s,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="nothing-appears" tabindex="-1">Nothing appears <a class="header-anchor" href="#nothing-appears" aria-label="Permalink to &quot;Nothing appears&quot;">​</a></h2><p>The package intentionally renders no UI. Install a website-owned renderer or use the full example. Ensure the controller is stable and <code>useQualification</code> is mounted. For a non-React subscriber, call <code>load()</code> yourself. Astro islands must hydrate.</p><h2 id="loading-fails" tabindex="-1">Loading fails <a class="header-anchor" href="#loading-fails" aria-label="Permalink to &quot;Loading fails&quot;">​</a></h2><p>Check <code>state.error</code> and the browser network panel. Confirm the API base URL, published slug/host and allowed website origin. The published funnel must start with a qualifier. A configured but missing form is an error, not permission to show a contact-only fallback. Render retry with <code>actions.load()</code>.</p><h2 id="npm-cannot-find-the-package" tabindex="-1">npm cannot find the package <a class="header-anchor" href="#npm-cannot-find-the-package" aria-label="Permalink to &quot;npm cannot find the package&quot;">​</a></h2><p>Use the public scope <code>@franchiseai/website-integrations</code>. Verify that your npm registry points to the public npm registry or a proxy that can resolve it. The private monorepo SDK is not a prerequisite. If a version has not yet been published, use a provided release tarball for evaluation; documentation alone is not proof of registry publication.</p><h2 id="questions-or-answers-reset-on-every-render" tabindex="-1">Questions or answers reset on every render <a class="header-anchor" href="#questions-or-answers-reset-on-every-render" aria-label="Permalink to &quot;Questions or answers reset on every render&quot;">​</a></h2><p>Do not create the controller inside the render body without <code>useState</code> or equivalent stable ownership. Recreate it only to start a new enquiry or change configuration. Keep one controller per visitor and form instance.</p><h2 id="email-is-read-only" tabindex="-1">Email is read-only <a class="header-anchor" href="#email-is-read-only" aria-label="Permalink to &quot;Email is read-only&quot;">​</a></h2><p>This is expected after a lead is created. Retrying a failed save must reuse that lead. The returning-applicant notice offers <code>useDifferentEmail</code>; it is not an account-switch action for an already created lead.</p><h2 id="answers-saved-but-the-form-shows-an-error" tabindex="-1">Answers saved but the form shows an error <a class="header-anchor" href="#answers-saved-but-the-form-shows-an-error" aria-label="Permalink to &quot;Answers saved but the form shows an error&quot;">​</a></h2><p><code>completion_error</code> means the final answers were saved but progress/entry resolution failed. Offer <code>submit()</code> to retry completion. Keep the answered form locked; the controller will not resubmit the answers during this recovery.</p><h2 id="rate-limited" tabindex="-1">Rate limited <a class="header-anchor" href="#rate-limited" aria-label="Permalink to &quot;Rate limited&quot;">​</a></h2><p>Render the wait indicated by <code>retryAt</code> and permit retry after it passes. The controller enforces the delay. Do not build a retry loop around requests. For live debugging, inspect HTTP status and retry metadata without logging personal information.</p><h2 id="no-email-arrives" tabindex="-1">No email arrives <a class="header-anchor" href="#no-email-arrives" aria-label="Permalink to &quot;No email arrives&quot;">​</a></h2><p>Demo mode never sends email. In live mode, <code>complete</code> and <code>resume_link_sent</code> are accepted/non-disclosing responses, not delivery receipts. Check the platform’s mail delivery and throttling with the responsible platform team. Do not work around this by exposing an application credential.</p><h2 id="my-design-needs-one-question-per-screen" tabindex="-1">My design needs one question per screen <a class="header-anchor" href="#my-design-needs-one-question-per-screen" aria-label="Permalink to &quot;My design needs one question per screen&quot;">​</a></h2><p>You can present a configured page with local visual substeps. The controller validates and saves the whole configured page when <code>submit()</code> is called. Per-question server saves, changing page order, adding file uploads, or skipping required published steps require contract changes; CSS alone cannot add them.</p>',19)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
